sys_script_include.script:
var DependentUtil = Class.create();
DependentUtil.prototype = {
    initialize: function() {
        this.DEPENDTENTS_TABLE = "x_1806928_health_0_dependents_info";
        this.USER_TABLE = "sys_user";
    },

    returnSysID: function(name) {

        var sysID = "";

        if (name) {
            var grInfo = new GlideRecord(this.USER_TABLE);
            grInfo.addQuery("user_name", name);
            grInfo.query();
            if (grInfo.next()) {
                sysID = grInfo.getValue("sys_id");
                return sysID;
            } else {
                return sysID;
            }
        }
    },

    type: 'DependentUtil'
};
